CREATE TABLE catalog_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, external_id VARCHAR(64) NOT NULL UNIQUE, item_type VARCHAR(16) NOT NULL, title_en VARCHAR(500) NOT NULL, title_ru VARCHAR(500) NOT NULL, comment_en TEXT, comment_ru TEXT, group_key VARCHAR(64) NOT NULL, group_name_en VARCHAR(255) NOT NULL, group_name_ru VARCHAR(255) NOT NULL, semantic_graphic_key VARCHAR(64) NOT NULL, frequency_limit INTEGER NOT NULL, frequency_period VARCHAR(16) NOT NULL, min_age INTEGER NOT NULL, max_age INTEGER NOT NULL, difficulty VARCHAR(16) NOT NULL, is_active BOOLEAN NOT NULL, sort_order INTEGER NOT NULL, coins INTEGER, price INTEGER, CONSTRAINT ck_catalog_item_type CHECK (item_type IN ('task','reward')), CONSTRAINT ck_catalog_frequency_positive CHECK (frequency_limit > 0), CONSTRAINT ck_catalog_age_range CHECK (min_age BETWEEN 0 AND 18 AND max_age BETWEEN min_age AND 18), CONSTRAINT ck_catalog_amounts CHECK ((item_type='task' AND coins>0 AND price IS NULL) OR (item_type='reward' AND price>0 AND coins IS NULL)));
CREATE INDEX idx_catalog_items_active_type_order ON catalog_items(item_type,is_active,sort_order,external_id);
